namespace Gatekeeper.Web.Domain;

/// <summary>
/// An access-control role. A role may have a parent role; permissions granted to
/// the parent are inherited by the child.
/// </summary>
public class Role
{
    public Guid Id { get; set; } = Guid.NewGuid();

    [Required, MaxLength(200)]
    public string Name { get; set; } = string.Empty;

    [MaxLength(1000)]
    public string? Description { get; set; }

    public Guid CustomerId { get; set; }
    public Customer? Customer { get; set; }

    /// <summary>Optional parent role. Grants on the parent are inherited.</summary>
    public Guid? ParentRoleId { get; set; }
    public Role? ParentRole { get; set; }
    public ICollection<Role> ChildRoles { get; set; } = new List<Role>();

    public ICollection<UserRole> UserRoles { get; set; } = new List<UserRole>();
    public ICollection<Grant> Grants { get; set; } = new List<Grant>();
}

