namespace Gatekeeper.Web.Domain;

/// <summary>
/// An immutable record of a single access-control decision: who asked for what,
/// on which resource, and whether Gatekeeper allowed or denied it.
/// </summary>
public class AuditLogEntry
{
    public Guid Id { get; set; } = Guid.NewGuid();

    public Guid CustomerId { get; set; }
    public Customer? Customer { get; set; }

    public DateTimeOffset Timestamp { get; set; } = DateTimeOffset.UtcNow;

    /// <summary>The user the decision was evaluated for ("who").</summary>
    public string? SubjectUserId { get; set; }
    public string SubjectDisplay { get; set; } = string.Empty;

    /// <summary>The permission requested ("what").</summary>
    public string PermissionName { get; set; } = string.Empty;

    /// <summary>The resource acted upon ("to whom / on what").</summary>
    public string ResourceName { get; set; } = string.Empty;

    public AccessResult Result { get; set; }

    /// <summary>Human-readable explanation of why the decision came out the way it did.</summary>
    public string Reason { get; set; } = string.Empty;
}

