using Gatekeeper.Web.Data;
using Gatekeeper.Web.Domain;
using Microsoft.EntityFrameworkCore;

namespace Gatekeeper.Web.Services;

/// <summary>
/// Default <see cref="IGatekeeper"/> implementation.
///
/// Resolution rules:
///  1. Collect the roles assigned directly to the subject.
///  2. Expand each role with its ancestor chain (parent, grandparent, ...) so
///     permissions are inherited down the tree.
///  3. Gather every grant on those roles that matches the requested permission and resource.
///  4. Deny overrides allow: any matching Deny loses the subject access.
///  5. Otherwise a matching Allow grants access.
///  6. With no matching grant at all, the default is to deny.
///
/// Every decision is written to the audit log before being returned.
/// </summary>
public class GatekeeperService(ApplicationDbContext db, ILogger<GatekeeperService> logger) : IGatekeeper
{
    public async Task<AccessDecision> EvaluateAsync(AccessRequest request, CancellationToken ct = default)
    {
        var decision = await ResolveAsync(request, ct);
        await RecordAsync(request, decision, ct);
        return decision;
    }

    private async Task<AccessDecision> ResolveAsync(AccessRequest request, CancellationToken ct)
    {
        var permission = await db.Permissions
            .FirstOrDefaultAsync(p => p.CustomerId == request.CustomerId && p.Name == request.PermissionName, ct);
        if (permission is null)
            return AccessDecision.Deny($"No permission named '{request.PermissionName}' exists for this customer.");

        var resource = await db.Resources
            .FirstOrDefaultAsync(r => r.CustomerId == request.CustomerId && r.Name == request.ResourceName, ct);
        if (resource is null)
            return AccessDecision.Deny($"No resource named '{request.ResourceName}' exists for this customer.");

        // All roles for the tenant, so we can walk the parent chain in memory.
        var roles = await db.AppRoles
            .Where(r => r.CustomerId == request.CustomerId)
            .Select(r => new { r.Id, r.Name, r.ParentRoleId })
            .ToListAsync(ct);
        var byId = roles.ToDictionary(r => r.Id);

        var directRoleIds = await db.UserRoles
            .Where(ur => ur.UserId == request.SubjectUserId)
            .Select(ur => ur.RoleId)
            .ToListAsync(ct);

        if (directRoleIds.Count == 0)
            return AccessDecision.Deny("Subject has no roles assigned; default deny.");

        // Expand each assigned role with its ancestors (cycle-safe).
        var effectiveRoleIds = new HashSet<Guid>();
        foreach (var roleId in directRoleIds)
        {
            var current = roleId;
            while (byId.TryGetValue(current, out var node) && effectiveRoleIds.Add(current))
            {
                if (node.ParentRoleId is Guid parent)
                    current = parent;
                else
                    break;
            }
        }

        var matching = await db.Grants
            .Where(g => g.CustomerId == request.CustomerId
                        && g.PermissionId == permission.Id
                        && g.ResourceId == resource.Id
                        && effectiveRoleIds.Contains(g.RoleId))
            .Select(g => new { g.Effect, g.RoleId })
            .ToListAsync(ct);

        if (matching.Count == 0)
            return AccessDecision.Deny(
                $"No grant on '{request.PermissionName}' for '{request.ResourceName}' via the subject's roles; default deny.");

        // Deny overrides allow.
        var deny = matching.FirstOrDefault(m => m.Effect == GrantEffect.Deny);
        if (deny is not null)
        {
            var roleName = byId.TryGetValue(deny.RoleId, out var r) ? r.Name : deny.RoleId.ToString();
            return AccessDecision.Deny($"Explicit deny via role '{roleName}' overrides any allow.");
        }

        var allow = matching.First();
        var allowRole = byId.TryGetValue(allow.RoleId, out var ar) ? ar.Name : allow.RoleId.ToString();
        return AccessDecision.Allow($"Allowed by grant via role '{allowRole}'.");
    }

    private async Task RecordAsync(AccessRequest request, AccessDecision decision, CancellationToken ct)
    {
        var subject = await db.Users
            .Where(u => u.Id == request.SubjectUserId)
            .Select(u => new { u.DisplayName, u.Email })
            .FirstOrDefaultAsync(ct);

        var entry = new AuditLogEntry
        {
            CustomerId = request.CustomerId,
            Timestamp = DateTimeOffset.UtcNow,
            SubjectUserId = request.SubjectUserId,
            SubjectDisplay = subject?.DisplayName is { Length: > 0 } d ? d
                : subject?.Email ?? request.SubjectUserId,
            PermissionName = request.PermissionName,
            ResourceName = request.ResourceName,
            Result = decision.Result,
            Reason = decision.Reason
        };

        db.AuditLog.Add(entry);
        await db.SaveChangesAsync(ct);

        logger.LogInformation(
            "Gatekeeper decision {Result}: subject {Subject} / {Permission} on {Resource} — {Reason}",
            decision.Result, entry.SubjectDisplay, request.PermissionName, request.ResourceName, decision.Reason);
    }
}

