@page "/Account/Register"
@using System.ComponentModel.DataAnnotations
@using Gatekeeper.Web.Data
@using Gatekeeper.Web.Domain
@using Microsoft.AspNetCore.Identity
@using Microsoft.EntityFrameworkCore

@inject UserManager<ApplicationUser> UserManager
@inject SignInManager<ApplicationUser> SignInManager
@inject ApplicationDbContext Db
@inject ILogger<Register> Logger
@inject IdentityRedirectManager RedirectManager

<PageTitle>Register — Gatekeeper</PageTitle>

<div class="auth-card">
    <h1>Create an account</h1>

    <StatusMessage Message="@Message" />

    <EditForm Model="Input" method="post" OnValidSubmit="RegisterUser" FormName="register">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" role="alert" />

        <div class="form-floating mb-3">
            <InputText @bind-Value="Input.DisplayName" class="form-control" placeholder="Jane Doe" />
            <label>Display name</label>
            <ValidationMessage For="() => Input.DisplayName" class="text-danger" />
        </div>
        <div class="form-floating mb-3">
            <InputText @bind-Value="Input.Email" class="form-control" autocomplete="username" placeholder="name@example.com" />
            <label>Email</label>
            <ValidationMessage For="() => Input.Email" class="text-danger" />
        </div>
        <div class="form-floating mb-3">
            <InputSelect @bind-Value="Input.CustomerId" class="form-select">
                <option value="">-- choose a customer --</option>
                @foreach (var c in customers)
                {
                    <option value="@c.Id">@c.Name (@c.PlanTier)</option>
                }
            </InputSelect>
            <label>Customer (tenant)</label>
            <ValidationMessage For="() => Input.CustomerId" class="text-danger" />
        </div>
        <div class="form-floating mb-3">
            <InputText type="password" @bind-Value="Input.Password" class="form-control" autocomplete="new-password" placeholder="password" />
            <label>Password</label>
            <ValidationMessage For="() => Input.Password" class="text-danger" />
        </div>
        <div class="form-floating mb-3">
            <InputText type="password" @bind-Value="Input.ConfirmPassword" class="form-control" autocomplete="new-password" placeholder="password" />
            <label>Confirm password</label>
            <ValidationMessage For="() => Input.ConfirmPassword" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary w-100">Register</button>
    </EditForm>

    <p class="mt-3"><a href="Account/Login">Already have an account? Log in</a></p>
</div>

@code {
    private List<Customer> customers = new();

    [SupplyParameterFromForm]
    private InputModel Input { get; set; } = new();

    [SupplyParameterFromQuery]
    private string? ReturnUrl { get; set; }

    [SupplyParameterFromQuery]
    private string? Message { get; set; }

    protected override async Task OnInitializedAsync()
    {
        customers = await Db.Customers.OrderBy(c => c.Name).ToListAsync();
    }

    private async Task RegisterUser()
    {
        var user = new ApplicationUser
        {
            UserName = Input.Email,
            Email = Input.Email,
            DisplayName = Input.DisplayName,
            CustomerId = Guid.Parse(Input.CustomerId!),
            EmailConfirmed = true
        };

        var result = await UserManager.CreateAsync(user, Input.Password);
        if (!result.Succeeded)
        {
            Message = string.Join(" ", result.Errors.Select(e => e.Description));
            return;
        }

        Logger.LogInformation("New account created for {Email}.", Input.Email);
        await SignInManager.SignInAsync(user, isPersistent: false);
        RedirectManager.RedirectTo(ReturnUrl);
    }

    private sealed class InputModel
    {
        [Required, MaxLength(200)]
        public string DisplayName { get; set; } = "";

        [Required, EmailAddress]
        public string Email { get; set; } = "";

        [Required(ErrorMessage = "Please choose a customer.")]
        public string? CustomerId { get; set; }

        [Required, StringLength(100, MinimumLength = 6)]
        [DataType(DataType.Password)]
        public string Password { get; set; } = "";

        [DataType(DataType.Password)]
        [Compare(nameof(Password), ErrorMessage = "The passwords do not match.")]
        public string ConfirmPassword { get; set; } = "";
    }
}

