        //   Viewer  ->  Editor  ->  Admin      (child inherits parent's grants)
        var viewer = new Role { CustomerId = acme.Id, Name = "Viewer", Description = "Read-only access." };
        var editor = new Role { CustomerId = acme.Id, Name = "Editor", Description = "Can edit documents.", ParentRole = viewer };
        var admin = new Role { CustomerId = acme.Id, Name = "Admin", Description = "Full access.", ParentRole = editor };
        db.AppRoles.AddRange(viewer, editor, admin);

        await db.SaveChangesAsync();

        // --- Grants ----------------------------------------------------------------
        db.Grants.AddRange(
            // Viewer can read documents (inherited by Editor and Admin).
            new Grant { CustomerId = acme.Id, RoleId = viewer.Id, PermissionId = read.Id, ResourceId = documents.Id, Effect = GrantEffect.Allow },
            // Editor can write documents.
            new Grant { CustomerId = acme.Id, RoleId = editor.Id, PermissionId = write.Id, ResourceId = documents.Id, Effect = GrantEffect.Allow },
            // Admin can delete documents and read+write billing.
            new Grant { CustomerId = acme.Id, RoleId = admin.Id, PermissionId = delete.Id, ResourceId = documents.Id, Effect = GrantEffect.Allow },
            new Grant { CustomerId = acme.Id, RoleId = admin.Id, PermissionId = read.Id, ResourceId = billing.Id, Effect = GrantEffect.Allow },
            new Grant { CustomerId = acme.Id, RoleId = admin.Id, PermissionId = write.Id, ResourceId = billing.Id, Effect = GrantEffect.Allow },
            // Editors are explicitly denied billing reads even though nothing grants it —
            // demonstrates deny-override when combined with future allows.
            new Grant { CustomerId = acme.Id, RoleId = editor.Id, PermissionId = read.Id, ResourceId = billing.Id, Effect = GrantEffect.Deny }
        );

        await db.SaveChangesAsync();

        await EnsureAdminAsync(userManager, db, acme.Id, admin.Id);
    }

    private static async Task EnsureAdminAsync(
        UserManager<ApplicationUser> userManager,
        ApplicationDbContext db,
        Guid customerId,
        Guid? adminRoleId = null)
    {
        var existing = await userManager.FindByEmailAsync(AdminEmail);
        if (existing is not null) return;

        var user = new ApplicationUser
        {
            UserName = AdminEmail,
            Email = AdminEmail,
            EmailConfirmed = true,
            DisplayName = "Acme Admin",
            CustomerId = customerId
        };
        var result = await userManager.CreateAsync(user, AdminPassword);
        if (!result.Succeeded)
            throw new InvalidOperationException(
                "Failed to seed admin user: " + string.Join("; ", result.Errors.Select(e => e.Description)));

        adminRoleId ??= await db.AppRoles
            .Where(r => r.CustomerId == customerId && r.Name == "Admin")
            .Select(r => (Guid?)r.Id)
            .FirstOrDefaultAsync();

        if (adminRoleId is Guid roleId)
        {
            db.UserRoles.Add(new UserRole { UserId = user.Id, RoleId = roleId });
            await db.SaveChangesAsync();
        }
    }
}

