using System.Security.Claims;
using Gatekeeper.Web.Data;
using Microsoft.EntityFrameworkCore;

namespace Gatekeeper.Web.Services;

/// <summary>Resolves the signed-in user's tenant (customer) for scoping admin pages.</summary>
public class TenantResolver(IDbContextFactory<ApplicationDbContext> factory)
{
    public record CurrentUser(string UserId, Guid CustomerId, string CustomerName, string Display);

    public async Task<CurrentUser?> GetAsync(ClaimsPrincipal? principal, CancellationToken ct = default)
    {
        var userId = principal?.FindFirstValue(ClaimTypes.NameIdentifier);
        if (string.IsNullOrEmpty(userId))
            return null;

        await using var db = await factory.CreateDbContextAsync(ct);
        var row = await db.Users
            .Where(u => u.Id == userId)
            .Select(u => new
            {
                u.Id,
                u.CustomerId,
                CustomerName = u.Customer!.Name,
                Display = string.IsNullOrEmpty(u.DisplayName) ? u.Email! : u.DisplayName
            })
            .FirstOrDefaultAsync(ct);

        return row is null ? null : new CurrentUser(row.Id, row.CustomerId, row.CustomerName, row.Display);
    }
}

