@page "/access-check"
@attribute [Authorize]
@rendermode InteractiveServer
@inject IDbContextFactory<ApplicationDbContext> DbFactory
@inject IGatekeeper Gatekeeper
@inject TenantResolver Tenant

<PageTitle>Access check — Gatekeeper</PageTitle>

<h1>Access check</h1>
<p class="text-muted">Ask Gatekeeper whether a user may perform an action on a resource. Every check is written to the audit log.</p>

@if (loading)
{
    <p><em>Loading…</em></p>
}
else if (current is null)
{
    <p>Unable to resolve your tenant.</p>
}
else
{
    <div class="row g-3 align-items-end">
        <div class="col-md-4">
            <label class="form-label">User</label>
            <select class="form-select" @bind="selectedUserId">
                @foreach (var u in users)
                {
                    <option value="@u.Id">@u.Display</option>
                }
            </select>
        </div>
        <div class="col-md-3">
            <label class="form-label">Permission</label>
            <select class="form-select" @bind="selectedPermission">
                @foreach (var p in permissions)
                {
                    <option value="@p">@p</option>
                }
            </select>
        </div>
        <div class="col-md-3">
            <label class="form-label">Resource</label>
            <select class="form-select" @bind="selectedResource">
                @foreach (var r in resources)
                {
                    <option value="@r">@r</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-primary w-100" @onclick="Evaluate" disabled="@evaluating">
                @(evaluating ? "Checking…" : "Check access")
            </button>
        </div>
    </div>

    @if (decision is not null)
    {
        <div class="alert @(decision.IsAllowed ? "alert-success" : "alert-danger") mt-4" role="alert">
            <h4 class="alert-heading">
                @(decision.IsAllowed ? "✅ Allowed" : "⛔ Denied")
            </h4>
            <p class="mb-1">
                <strong>@lastUserDisplay</strong> →
                <code>@lastPermission</code> on <code>@lastResource</code>
            </p>
            <hr />
            <p class="mb-0">@decision.Reason</p>
        </div>
        <p class="text-muted">Recorded in the <a href="audit">audit log</a>.</p>
    }
}

@code {
    [CascadingParameter] private Task<AuthenticationState>? AuthState { get; set; }

    private bool loading = true;
    private bool evaluating;
    private TenantResolver.CurrentUser? current;

    private List<UserRow> users = new();
    private List<string> permissions = new();
    private List<string> resources = new();

    private string? selectedUserId;
    private string? selectedPermission;
    private string? selectedResource;

    private AccessDecision? decision;
    private string lastUserDisplay = "", lastPermission = "", lastResource = "";

    private record UserRow(string Id, string Display);

    protected override async Task OnInitializedAsync()
    {
        var authState = AuthState is null ? null : await AuthState;
        current = await Tenant.GetAsync(authState?.User);
        if (current is not null)
        {
            await using var db = await DbFactory.CreateDbContextAsync();
            var cid = current.CustomerId;

            users = await db.Users.Where(u => u.CustomerId == cid)
                .OrderBy(u => u.DisplayName)
                .Select(u => new UserRow(u.Id, string.IsNullOrEmpty(u.DisplayName) ? u.Email! : u.DisplayName))
                .ToListAsync();
            permissions = await db.Permissions.Where(p => p.CustomerId == cid)
                .OrderBy(p => p.Name).Select(p => p.Name).ToListAsync();
            resources = await db.Resources.Where(r => r.CustomerId == cid)
                .OrderBy(r => r.Name).Select(r => r.Name).ToListAsync();

            selectedUserId = users.FirstOrDefault()?.Id;
            selectedPermission = permissions.FirstOrDefault();
            selectedResource = resources.FirstOrDefault();
        }
        loading = false;
    }

    private async Task Evaluate()
    {
        if (current is null || selectedUserId is null || selectedPermission is null || selectedResource is null)
            return;

        evaluating = true;
        try
        {
            decision = await Gatekeeper.EvaluateAsync(new AccessRequest(
                current.CustomerId, selectedUserId, selectedPermission, selectedResource));

            lastUserDisplay = users.FirstOrDefault(u => u.Id == selectedUserId)?.Display ?? selectedUserId;
            lastPermission = selectedPermission;
            lastResource = selectedResource;
        }
        finally
        {
            evaluating = false;
        }
    }
}

