@code {
    [CascadingParameter] private Task<AuthenticationState>? AuthState { get; set; }

    private TenantResolver.CurrentUser? current;

    private List<Lookup> roles = new();
    private List<Lookup> permissions = new();
    private List<Lookup> resources = new();
    private List<GrantRow> grants = new();

    private string? roleId, permissionId, resourceId;
    private GrantEffect effect = GrantEffect.Allow;
    private string? error;
    private bool saving;

