    private record GrantRow(Guid Id, string Role, string Permission, string Resource, GrantEffect Effect);

    protected override async Task OnInitializedAsync()
    {
        var authState = AuthState is null ? null : await AuthState;
        current = await Tenant.GetAsync(authState?.User);
        await Load();
    }

    private async Task Load()
    {
        if (current is null) return;
        await using var db = await DbFactory.CreateDbContextAsync();
        var cid = current.CustomerId;

        roles = await db.AppRoles.Where(r => r.CustomerId == cid).OrderBy(r => r.Name)
            .Select(r => new Lookup(r.Id, r.Name)).ToListAsync();
        permissions = await db.Permissions.Where(p => p.CustomerId == cid).OrderBy(p => p.Name)
            .Select(p => new Lookup(p.Id, p.Name)).ToListAsync();
        resources = await db.Resources.Where(r => r.CustomerId == cid).OrderBy(r => r.Name)
            .Select(r => new Lookup(r.Id, r.Name)).ToListAsync();

        grants = await db.Grants.Where(g => g.CustomerId == cid)
            .OrderBy(g => g.Role!.Name).ThenBy(g => g.Resource!.Name)
            .Select(g => new GrantRow(g.Id, g.Role!.Name, g.Permission!.Name, g.Resource!.Name, g.Effect))
            .ToListAsync();

        roleId ??= roles.FirstOrDefault()?.Id.ToString();
        permissionId ??= permissions.FirstOrDefault()?.Id.ToString();
        resourceId ??= resources.FirstOrDefault()?.Id.ToString();
    }

    private async Task AddGrant()
    {
        error = null;
        if (current is null) return;
        if (roleId is null || permissionId is null || resourceId is null)
        {
            error = "Pick a role, permission and resource first (create them on the other pages if empty).";
            return;
        }

        saving = true;
        try
        {
            await using var db = await DbFactory.CreateDbContextAsync();
            db.Grants.Add(new Grant
            {
                CustomerId = current.CustomerId,
                RoleId = Guid.Parse(roleId),
                PermissionId = Guid.Parse(permissionId),
                ResourceId = Guid.Parse(resourceId),
                Effect = effect
            });
            await db.SaveChangesAsync();
            await Load();
        }
        catch (Exception ex)
        {
            error = (ex.InnerException?.Message ?? ex.Message).Contains("IX_", StringComparison.OrdinalIgnoreCase)
                ? "That role already has a grant for this permission and resource."
                : (ex.InnerException?.Message ?? ex.Message);
        }
        finally
        {
            saving = false;
        }
    }

    private async Task Delete(Guid id)
    {
        await using var db = await DbFactory.CreateDbContextAsync();
        var grant = await db.Grants.FindAsync(id);
        if (grant is not null)
        {
            db.Grants.Remove(grant);
            await db.SaveChangesAsync();
        }
        await Load();
    }
}

