    {
        var msg = ex.InnerException?.Message ?? ex.Message;
        return msg.Contains("IX_", StringComparison.OrdinalIgnoreCase) || msg.Contains("duplicate", StringComparison.OrdinalIgnoreCase)
            ? $"A {what} with that name already exists."
            : msg;
    }
