@page "/customers"
@attribute [Authorize]
@rendermode InteractiveServer
@inject IDbContextFactory<ApplicationDbContext> DbFactory

<PageTitle>Customers — Gatekeeper</PageTitle>

<h1>Customers</h1>
<p class="text-muted">Customers are the tenants. Each has a plan tier.</p>

<div class="card mb-4">
    <div class="card-header">Add a customer</div>
    <div class="card-body">
        <div class="row g-2 align-items-end">
            <div class="col-md-5">
                <label class="form-label">Name</label>
                <input class="form-control" @bind="newName" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Plan tier</label>
                <select class="form-select" @bind="newTier">
                    @foreach (var t in Enum.GetValues<PlanTier>())
                    {
                        <option value="@t">@t</option>
                    }
                </select>
            </div>
            <div class="col-md-3">
                <button class="btn btn-primary" @onclick="AddCustomer">Add customer</button>
            </div>
        </div>
        @if (!string.IsNullOrEmpty(error))
        {
            <div class="text-danger mt-2">@error</div>
        }
    </div>
</div>

<table class="table align-middle">
    <thead>
        <tr><th>Name</th><th>Plan tier</th><th>Users</th><th>Created</th></tr>
    </thead>
    <tbody>
        @foreach (var c in customers)
        {
            <tr>
                <td><strong>@c.Name</strong></td>
                <td><span class="badge @TierClass(c.PlanTier)">@c.PlanTier</span></td>
                <td>@c.UserCount</td>
                <td>@c.CreatedAt.ToLocalTime().ToString("yyyy-MM-dd")</td>
            </tr>
        }
    </tbody>
</table>

@code {
    private List<Row> customers = new();
    private string newName = "";
    private PlanTier newTier = PlanTier.Free;
    private string? error;

    private record Row(Guid Id, string Name, PlanTier PlanTier, int UserCount, DateTimeOffset CreatedAt);

    protected override async Task OnInitializedAsync() => await Load();

    private async Task Load()
    {
        await using var db = await DbFactory.CreateDbContextAsync();
        customers = await db.Customers.OrderBy(c => c.Name)
            .Select(c => new Row(c.Id, c.Name, c.PlanTier, c.Users.Count, c.CreatedAt))
            .ToListAsync();
    }

    private async Task AddCustomer()
    {
        error = null;
        if (string.IsNullOrWhiteSpace(newName))
        {
            error = "Name is required.";
            return;
        }
        await using var db = await DbFactory.CreateDbContextAsync();
        db.Customers.Add(new Customer { Name = newName.Trim(), PlanTier = newTier });
        await db.SaveChangesAsync();
        newName = ""; newTier = PlanTier.Free;
        await Load();
    }

    private static string TierClass(PlanTier tier) => tier switch
    {
        PlanTier.Enterprise => "bg-primary",
        PlanTier.Pro => "bg-info text-dark",
        _ => "bg-secondary"
    };
}

