@page "/audit"
@attribute [Authorize]
@rendermode InteractiveServer
@inject IDbContextFactory<ApplicationDbContext> DbFactory
@inject TenantResolver Tenant

<PageTitle>Audit log — Gatekeeper</PageTitle>

<h1>Audit log</h1>
<p class="text-muted">Every decision Gatekeeper makes is recorded here — who asked for what, on which resource, and how it was ruled.</p>

@if (current is null)
{
    <p><em>Loading…</em></p>
}
else
{
    <div class="d-flex gap-2 mb-3">
        <select class="form-select w-auto" @bind="filter" @bind:after="Load">
            <option value="">All decisions</option>
            <option value="Allowed">Allowed only</option>
            <option value="Denied">Denied only</option>
        </select>
        <button class="btn btn-outline-secondary" @onclick="Load">Refresh</button>
    </div>

    @if (entries.Count == 0)
    {
        <p class="text-muted">No decisions recorded yet. Run an <a href="access-check">access check</a>.</p>
    }
    else
    {
        <table class="table table-sm align-middle">
            <thead>
                <tr><th>When (UTC)</th><th>Subject</th><th>Permission</th><th>Resource</th><th>Result</th><th>Reason</th></tr>
            </thead>
            <tbody>
                @foreach (var e in entries)
                {
                    <tr>
                        <td class="text-nowrap">@e.Timestamp.UtcDateTime.ToString("yyyy-MM-dd HH:mm:ss")</td>
                        <td>@e.SubjectDisplay</td>
                        <td><code>@e.PermissionName</code></td>
                        <td><code>@e.ResourceName</code></td>
                        <td>
                            <span class="badge @(e.Result == AccessResult.Allowed ? "bg-success" : "bg-danger")">@e.Result</span>
                        </td>
                        <td class="small text-muted">@e.Reason</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

