@using System.Net.Http
@using System.Net.Http.Json
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@using Microsoft.AspNetCore.Components.Forms
@using Microsoft.AspNetCore.Components.Routing
@using Microsoft.AspNetCore.Components.Web
@using static Microsoft.AspNetCore.Components.Web.RenderMode
@using Microsoft.AspNetCore.Components.Web.Virtualization
@using Microsoft.JSInterop
@using Gatekeeper.Web
@using Gatekeeper.Web.Components
@using Gatekeeper.Web.Components.Account
@using Gatekeeper.Web.Components.Account.Shared
@using Gatekeeper.Web.Components.Shared
@using Gatekeeper.Web.Components.Layout
@using Gatekeeper.Web.Data
@using Gatekeeper.Web.Domain
@using Gatekeeper.Web.Services

using Gatekeeper.Web.Domain;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace Gatekeeper.Web.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options)
    : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Customer> Customers => Set<Customer>();
    public DbSet<Role> AppRoles => Set<Role>();
    public DbSet<UserRole> UserRoles => Set<UserRole>();
    public DbSet<Permission> Permissions => Set<Permission>();
    public DbSet<Resource> Resources => Set<Resource>();
    public DbSet<Grant> Grants => Set<Grant>();
    public DbSet<AuditLogEntry> AuditLog => Set<AuditLogEntry>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<ApplicationUser>(e =>
        {
            e.HasOne(u => u.Customer)
                .WithMany(c => c.Users)
                .HasForeignKey(u => u.CustomerId)
                .OnDelete(DeleteBehavior.Restrict);
        });

        builder.Entity<Role>(e =>
        {
            e.HasOne(r => r.Customer)
                .WithMany(c => c.Roles)
                .HasForeignKey(r => r.CustomerId)
                .OnDelete(DeleteBehavior.Cascade);

            e.HasOne(r => r.ParentRole)
                .WithMany(r => r.ChildRoles)
                .HasForeignKey(r => r.ParentRoleId)
                .OnDelete(DeleteBehavior.Restrict);

            e.HasIndex(r => new { r.CustomerId, r.Name }).IsUnique();
        });

        builder.Entity<UserRole>(e =>
        {
            e.HasKey(ur => new { ur.UserId, ur.RoleId });

            e.HasOne(ur => ur.User)
                .WithMany(u => u.UserRoles)
                .HasForeignKey(ur => ur.UserId)
                .OnDelete(DeleteBehavior.Cascade);

            e.HasOne(ur => ur.Role)
                .WithMany(r => r.UserRoles)
                .HasForeignKey(ur => ur.RoleId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        builder.Entity<Permission>(e =>
        {
            e.HasOne(p => p.Customer)
                .WithMany(c => c.Permissions)
                .HasForeignKey(p => p.CustomerId)
                .OnDelete(DeleteBehavior.Cascade);

            e.HasIndex(p => new { p.CustomerId, p.Name }).IsUnique();
        });

        builder.Entity<Resource>(e =>
        {
            e.HasOne(r => r.Customer)
                .WithMany(c => c.Resources)
                .HasForeignKey(r => r.CustomerId)
                .OnDelete(DeleteBehavior.Cascade);

            e.HasIndex(r => new { r.CustomerId, r.Name }).IsUnique();
        });

        builder.Entity<Grant>(e =>
        {
            e.HasOne(g => g.Customer)
                .WithMany(c => c.Grants)
                .HasForeignKey(g => g.CustomerId)
                .OnDelete(DeleteBehavior.Cascade);

            // Restrict on the lookups so a grant can't be orphaned by a cascade
            // arriving from two directions (Postgres rejects multiple cascade paths).
            e.HasOne(g => g.Role)
                .WithMany(r => r.Grants)
                .HasForeignKey(g => g.RoleId)
                .OnDelete(DeleteBehavior.Cascade);

            e.HasOne(g => g.Permission)
                .WithMany(p => p.Grants)
                .HasForeignKey(g => g.PermissionId)
                .OnDelete(DeleteBehavior.Restrict);

            e.HasOne(g => g.Resource)
                .WithMany(r => r.Grants)
                .HasForeignKey(g => g.ResourceId)
                .OnDelete(DeleteBehavior.Restrict);

            e.HasIndex(g => new { g.RoleId, g.PermissionId, g.ResourceId }).IsUnique();
        });

        builder.Entity<AuditLogEntry>(e =>
        {
            e.HasOne(a => a.Customer)
                .WithMany()
                .HasForeignKey(a => a.CustomerId)
                .OnDelete(DeleteBehavior.Cascade);

            e.HasIndex(a => a.Timestamp);
            e.HasIndex(a => new { a.CustomerId, a.Timestamp });
        });
    }
}

using Gatekeeper.Web.Data;
using Gatekeeper.Web.Domain;
using Microsoft.EntityFrameworkCore;

namespace Gatekeeper.Web.Services;

/// <summary>
/// Default <see cref="IGatekeeper"/> implementation.
///
/// Resolution rules:
///  1. Collect the roles assigned directly to the subject.
///  2. Expand each role with its ancestor chain (parent, grandparent, ...) so
///     permissions are inherited down the tree.
///  3. Gather every grant on those roles that matches the requested permission and resource.
///  4. Deny overrides allow: any matching Deny loses the subject access.
///  5. Otherwise a matching Allow grants access.
///  6. With no matching grant at all, the default is to deny.
///
/// Every decision is written to the audit log before being returned.
/// </summary>
public class GatekeeperService(ApplicationDbContext db, ILogger<GatekeeperService> logger) : IGatekeeper
{
    public async Task<AccessDecision> EvaluateAsync(AccessRequest request, CancellationToken ct = default)
    {
        var decision = await ResolveAsync(request, ct);
        await RecordAsync(request, decision, ct);
        return decision;
    }

    private async Task<AccessDecision> ResolveAsync(AccessRequest request, CancellationToken ct)
    {
        var permission = await db.Permissions
            .FirstOrDefaultAsync(p => p.CustomerId == request.CustomerId && p.Name == request.PermissionName, ct);
        if (permission is null)
            return AccessDecision.Deny($"No permission named '{request.PermissionName}' exists for this customer.");

        var resource = await db.Resources
            .FirstOrDefaultAsync(r => r.CustomerId == request.CustomerId && r.Name == request.ResourceName, ct);
        if (resource is null)
            return AccessDecision.Deny($"No resource named '{request.ResourceName}' exists for this customer.");

        // All roles for the tenant, so we can walk the parent chain in memory.
        var roles = await db.AppRoles
            .Where(r => r.CustomerId == request.CustomerId)
            .Select(r => new { r.Id, r.Name, r.ParentRoleId })
            .ToListAsync(ct);
        var byId = roles.ToDictionary(r => r.Id);

        var directRoleIds = await db.UserRoles
            .Where(ur => ur.UserId == request.SubjectUserId)
            .Select(ur => ur.RoleId)
            .ToListAsync(ct);

        if (directRoleIds.Count == 0)
            return AccessDecision.Deny("Subject has no roles assigned; default deny.");

        // Expand each assigned role with its ancestors (cycle-safe).
        var effectiveRoleIds = new HashSet<Guid>();
        foreach (var roleId in directRoleIds)
        {
            var current = roleId;
            while (byId.TryGetValue(current, out var node) && effectiveRoleIds.Add(current))
            {
                if (node.ParentRoleId is Guid parent)
                    current = parent;
                else
                    break;
            }
        }

        var matching = await db.Grants
            .Where(g => g.CustomerId == request.CustomerId
                        && g.PermissionId == permission.Id
                        && g.ResourceId == resource.Id
                        && effectiveRoleIds.Contains(g.RoleId))
            .Select(g => new { g.Effect, g.RoleId })
            .ToListAsync(ct);

        if (matching.Count == 0)
            return AccessDecision.Deny(
                $"No grant on '{request.PermissionName}' for '{request.ResourceName}' via the subject's roles; default deny.");

        // Deny overrides allow.
        var deny = matching.FirstOrDefault(m => m.Effect == GrantEffect.Deny);
        if (deny is not null)
        {
            var roleName = byId.TryGetValue(deny.RoleId, out var r) ? r.Name : deny.RoleId.ToString();
            return AccessDecision.Deny($"Explicit deny via role '{roleName}' overrides any allow.");
        }

        var allow = matching.First();
        var allowRole = byId.TryGetValue(allow.RoleId, out var ar) ? ar.Name : allow.RoleId.ToString();
        return AccessDecision.Allow($"Allowed by grant via role '{allowRole}'.");
    }

    private async Task RecordAsync(AccessRequest request, AccessDecision decision, CancellationToken ct)
    {
        var subject = await db.Users
            .Where(u => u.Id == request.SubjectUserId)
            .Select(u => new { u.DisplayName, u.Email })
            .FirstOrDefaultAsync(ct);

        var entry = new AuditLogEntry
        {
            CustomerId = request.CustomerId,
            Timestamp = DateTimeOffset.UtcNow,
            SubjectUserId = request.SubjectUserId,
            SubjectDisplay = subject?.DisplayName is { Length: > 0 } d ? d
                : subject?.Email ?? request.SubjectUserId,
            PermissionName = request.PermissionName,
            ResourceName = request.ResourceName,
            Result = decision.Result,
            Reason = decision.Reason
        };

        db.AuditLog.Add(entry);
        await db.SaveChangesAsync(ct);

        logger.LogInformation(
            "Gatekeeper decision {Result}: subject {Subject} / {Permission} on {Resource} — {Reason}",
            decision.Result, entry.SubjectDisplay, request.PermissionName, request.ResourceName, decision.Reason);
    }
}

using Gatekeeper.Web.Domain;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;

namespace Gatekeeper.Web.Data;

/// <summary>
/// Applies migrations and seeds a demo tenant so the console has something to show on
/// first run: a customer, permissions, resources, an inheriting role tree, grants
/// (including a deny that overrides an inherited allow), and an admin login.
/// </summary>
public static class DbSeeder
{
    public const string AdminEmail = "admin@acme.test";
    public const string AdminPassword = "Passw0rd!";

    public static async Task SeedAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var sp = scope.ServiceProvider;

        var db = sp.GetRequiredService<ApplicationDbContext>();
        await db.Database.MigrateAsync();

        var userManager = sp.GetRequiredService<UserManager<ApplicationUser>>();

        // --- Customers (tenants) ---------------------------------------------------
        var acme = await db.Customers.FirstOrDefaultAsync(c => c.Name == "Acme Corp");
        if (acme is null)
        {
            acme = new Customer { Name = "Acme Corp", PlanTier = PlanTier.Enterprise };
            db.Customers.Add(acme);

            db.Customers.Add(new Customer { Name = "Globex", PlanTier = PlanTier.Pro });
            db.Customers.Add(new Customer { Name = "Initech", PlanTier = PlanTier.Free });
            await db.SaveChangesAsync();
        }

        // Everything below seeds the Acme tenant only.
        if (await db.AppRoles.AnyAsync(r => r.CustomerId == acme.Id))
        {
            await EnsureAdminAsync(userManager, db, acme.Id);
            return;
        }

        // --- Permissions -----------------------------------------------------------
        var read = new Permission { CustomerId = acme.Id, Name = "read", Description = "View a resource." };
        var write = new Permission { CustomerId = acme.Id, Name = "write", Description = "Create or modify a resource." };
        var delete = new Permission { CustomerId = acme.Id, Name = "delete", Description = "Remove a resource." };
        db.Permissions.AddRange(read, write, delete);

        // --- Resources -------------------------------------------------------------
        var documents = new Resource { CustomerId = acme.Id, Name = "documents", Description = "Shared documents." };
        var billing = new Resource { CustomerId = acme.Id, Name = "billing", Description = "Invoices and payment settings." };
        db.Resources.AddRange(documents, billing);

        // --- Roles (with inheritance) ----------------------------------------------
        //   Viewer  ->  Editor  ->  Admin      (child inherits parent's grants)
        var viewer = new Role { CustomerId = acme.Id, Name = "Viewer", Description = "Read-only access." };
        var editor = new Role { CustomerId = acme.Id, Name = "Editor", Description = "Can edit documents.", ParentRole = viewer };
        var admin = new Role { CustomerId = acme.Id, Name = "Admin", Description = "Full access.", ParentRole = editor };
        db.AppRoles.AddRange(viewer, editor, admin);

        await db.SaveChangesAsync();

        // --- Grants ----------------------------------------------------------------
        db.Grants.AddRange(
            // Viewer can read documents (inherited by Editor and Admin).
            new Grant { CustomerId = acme.Id, RoleId = viewer.Id, PermissionId = read.Id, ResourceId = documents.Id, Effect = GrantEffect.Allow },
            // Editor can write documents.
            new Grant { CustomerId = acme.Id, RoleId = editor.Id, PermissionId = write.Id, ResourceId = documents.Id, Effect = GrantEffect.Allow },
            // Admin can delete documents and read+write billing.
            new Grant { CustomerId = acme.Id, RoleId = admin.Id, PermissionId = delete.Id, ResourceId = documents.Id, Effect = GrantEffect.Allow },
            new Grant { CustomerId = acme.Id, RoleId = admin.Id, PermissionId = read.Id, ResourceId = billing.Id, Effect = GrantEffect.Allow },
            new Grant { CustomerId = acme.Id, RoleId = admin.Id, PermissionId = write.Id, ResourceId = billing.Id, Effect = GrantEffect.Allow },
            // Editors are explicitly denied billing reads even though nothing grants it —
            // demonstrates deny-override when combined with future allows.
            new Grant { CustomerId = acme.Id, RoleId = editor.Id, PermissionId = read.Id, ResourceId = billing.Id, Effect = GrantEffect.Deny }
        );

        await db.SaveChangesAsync();

        await EnsureAdminAsync(userManager, db, acme.Id, admin.Id);
    }

    private static async Task EnsureAdminAsync(
        UserManager<ApplicationUser> userManager,
        ApplicationDbContext db,
        Guid customerId,
        Guid? adminRoleId = null)
    {
        var existing = await userManager.FindByEmailAsync(AdminEmail);
        if (existing is not null) return;

        var user = new ApplicationUser
        {
            UserName = AdminEmail,
            Email = AdminEmail,
            EmailConfirmed = true,
            DisplayName = "Acme Admin",
            CustomerId = customerId
        };
        var result = await userManager.CreateAsync(user, AdminPassword);
        if (!result.Succeeded)
            throw new InvalidOperationException(
                "Failed to seed admin user: " + string.Join("; ", result.Errors.Select(e => e.Description)));

        adminRoleId ??= await db.AppRoles
            .Where(r => r.CustomerId == customerId && r.Name == "Admin")
            .Select(r => (Guid?)r.Id)
            .FirstOrDefaultAsync();

        if (adminRoleId is Guid roleId)
        {
            db.UserRoles.Add(new UserRole { UserId = user.Id, RoleId = roleId });
            await db.SaveChangesAsync();
        }
    }
}

@page "/users"
@attribute [Authorize]
@rendermode InteractiveServer
@inject IDbContextFactory<ApplicationDbContext> DbFactory
@inject UserManager<ApplicationUser> UserManager
@inject TenantResolver Tenant

<PageTitle>Users — Gatekeeper</PageTitle>

<h1>Users</h1>

@if (current is null)
{
    <p><em>Loading…</em></p>
}
else
{
    <p class="text-muted">Users in tenant <strong>@current.CustomerName</strong>.</p>

    <div class="card mb-4">
        <div class="card-header">Add a user</div>
        <div class="card-body">
            <div class="row g-2 align-items-end">
                <div class="col-md-3">
                    <label class="form-label">Display name</label>
                    <input class="form-control" @bind="newDisplayName" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Email</label>
                    <input class="form-control" @bind="newEmail" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Password</label>
                    <input class="form-control" type="password" @bind="newPassword" />
                </div>
                <div class="col-md-3">
                    <button class="btn btn-primary" @onclick="AddUser" disabled="@saving">Add user</button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(error))
            {
                <div class="text-danger mt-2">@error</div>
            }
        </div>
    </div>

    <table class="table table-hover align-middle">
        <thead>
            <tr><th>Name</th><th>Email</th><th>Roles</th><th></th></tr>
        </thead>
        <tbody>
            @foreach (var u in users)
            {
                <tr>
                    <td>@u.Display</td>
                    <td>@u.Email</td>
                    <td>
                        @if (u.Roles.Count == 0)
                        {
                            <span class="text-muted">—</span>
                        }
                        else
                        {
                            @foreach (var r in u.Roles)
                            {
                                <span class="badge bg-secondary me-1">@r</span>
                            }
                        }
                    </td>
                    <td class="text-end">
                        <button class="btn btn-sm btn-outline-secondary" @onclick="() => EditRoles(u.Id)">Manage roles</button>
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (editingUser is not null)
    {
        <div class="card">
            <div class="card-header">Roles for @editingUser.Display</div>
            <div class="card-body">
                @foreach (var role in allRoles)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox"
                               checked="@editingRoleIds.Contains(role.Id)"
                               @onchange="e => ToggleRole(role.Id, (bool)e.Value!)" />
                        <label class="form-check-label">@role.Name</label>
                    </div>
                }
                <button class="btn btn-primary mt-2" @onclick="SaveRoles">Save</button>
                <button class="btn btn-link mt-2" @onclick="() => editingUser = null">Cancel</button>
            </div>
        </div>
    }
}

@code {
    [CascadingParameter] private Task<AuthenticationState>? AuthState { get; set; }

    private TenantResolver.CurrentUser? current;
    private List<UserRow> users = new();
    private List<RoleRow> allRoles = new();

    private string newDisplayName = "", newEmail = "", newPassword = "";
    private string? error;
    private bool saving;

    private UserRow? editingUser;
    private HashSet<Guid> editingRoleIds = new();

    private record RoleRow(Guid Id, string Name);
    private class UserRow
    {
        public string Id { get; set; } = "";
        public string Display { get; set; } = "";
        public string Email { get; set; } = "";
        public List<string> Roles { get; set; } = new();
    }

    protected override async Task OnInitializedAsync()
    {
        var authState = AuthState is null ? null : await AuthState;
        current = await Tenant.GetAsync(authState?.User);
        await Load();
    }

    private async Task Load()
    {
        if (current is null) return;
        await using var db = await DbFactory.CreateDbContextAsync();
        var cid = current.CustomerId;

        allRoles = await db.AppRoles.Where(r => r.CustomerId == cid)
            .OrderBy(r => r.Name).Select(r => new RoleRow(r.Id, r.Name)).ToListAsync();

        users = await db.Users.Where(u => u.CustomerId == cid)
            .OrderBy(u => u.DisplayName)
            .Select(u => new UserRow
            {
                Id = u.Id,
                Display = string.IsNullOrEmpty(u.DisplayName) ? u.Email! : u.DisplayName,
                Email = u.Email!,
                Roles = u.UserRoles.Select(ur => ur.Role!.Name).OrderBy(n => n).ToList()
            })
            .ToListAsync();
    }

    private async Task AddUser()
    {
        error = null;
        if (current is null) return;
        if (string.IsNullOrWhiteSpace(newEmail) || string.IsNullOrWhiteSpace(newPassword))
        {
            error = "Email and password are required.";
            return;
        }

        saving = true;
        try
        {
            var user = new ApplicationUser
            {
                UserName = newEmail,
                Email = newEmail,
                EmailConfirmed = true,
                DisplayName = newDisplayName,
                CustomerId = current.CustomerId
            };
            var result = await UserManager.CreateAsync(user, newPassword);
            if (!result.Succeeded)
            {
                error = string.Join(" ", result.Errors.Select(e => e.Description));
                return;
            }
            newDisplayName = newEmail = newPassword = "";
            await Load();
        }
        finally
        {
            saving = false;
        }
    }

    private void EditRoles(string userId)
    {
        editingUser = users.First(u => u.Id == userId);
        editingRoleIds = allRoles
            .Where(r => editingUser.Roles.Contains(r.Name))
            .Select(r => r.Id).ToHashSet();
    }

    private void ToggleRole(Guid roleId, bool on)
    {
        if (on) editingRoleIds.Add(roleId);
        else editingRoleIds.Remove(roleId);
    }

    private async Task SaveRoles()
    {
        if (editingUser is null) return;
        await using var db = await DbFactory.CreateDbContextAsync();

        var existing = await db.UserRoles.Where(ur => ur.UserId == editingUser.Id).ToListAsync();
        db.UserRoles.RemoveRange(existing);
        foreach (var roleId in editingRoleIds)
            db.UserRoles.Add(new UserRole { UserId = editingUser.Id, RoleId = roleId });
        await db.SaveChangesAsync();

        editingUser = null;
        await Load();
    }
}

