using Gatekeeper.Web.Data;
using Gatekeeper.Web.Domain;
using Gatekeeper.Web.Services;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

const string cs = "Host=127.0.0.1;Port=5432;Database=gatekeeper;Username=postgres";

var services = new ServiceCollection();
services.AddLogging(b => b.AddSimpleConsole().SetMinimumLevel(LogLevel.Warning));
services.AddDbContextFactory<ApplicationDbContext>(o => o.UseNpgsql(cs));
services.AddScoped<ApplicationDbContext>(sp =>
    sp.GetRequiredService<IDbContextFactory<ApplicationDbContext>>().CreateDbContext());
services.AddScoped<IGatekeeper, GatekeeperService>();
var sp = services.BuildServiceProvider();

await using var db = await sp.GetRequiredService<IDbContextFactory<ApplicationDbContext>>().CreateDbContextAsync();
var acme = await db.Customers.FirstAsync(c => c.Name == "Acme Corp");
var admin = await db.Users.FirstAsync(u => u.Email == "admin@acme.test");

// Create a role-less user to prove default-deny for someone with no roles.
var nobody = await db.Users.FirstOrDefaultAsync(u => u.Email == "nobody@acme.test");
if (nobody is null)
{
    nobody = new ApplicationUser { UserName = "nobody@acme.test", Email = "nobody@acme.test", CustomerId = acme.Id, DisplayName = "Nobody" };
    db.Users.Add(nobody);
    await db.SaveChangesAsync();
}

var auditBefore = await db.AuditLog.CountAsync(a => a.CustomerId == acme.Id);

(string subjectId, string perm, string res, AccessResult expect, string why)[] cases =
{
    (admin.Id,  "read",   "documents", AccessResult.Allowed, "Viewer grant inherited by Admin"),
    (admin.Id,  "write",  "documents", AccessResult.Allowed, "Editor grant inherited by Admin"),
    (admin.Id,  "delete", "documents", AccessResult.Allowed, "Admin's own grant"),
    (admin.Id,  "read",   "billing",   AccessResult.Denied,  "Editor DENY inherited by Admin overrides Admin's allow"),
    (admin.Id,  "delete", "billing",   AccessResult.Denied,  "no grant -> default deny"),
    (nobody.Id, "read",   "documents", AccessResult.Denied,  "subject has no roles"),
    (admin.Id,  "read",   "ghost",     AccessResult.Denied,  "unknown resource"),
};

int pass = 0, fail = 0;
using var scope = sp.CreateScope();
var gk = scope.ServiceProvider.GetRequiredService<IGatekeeper>();
foreach (var c in cases)
{
    var d = await gk.EvaluateAsync(new AccessRequest(acme.Id, c.subjectId, c.perm, c.res));
    var ok = d.Result == c.expect;
    if (ok) pass++; else fail++;
    Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {c.perm,-7} {c.res,-10} -> {d.Result,-8} (expected {c.expect}) — {c.why}");
    if (!ok) Console.WriteLine($"        reason returned: {d.Reason}");
}

var auditAfter = await db.AuditLog.CountAsync(a => a.CustomerId == acme.Id);
var written = auditAfter - auditBefore;
Console.WriteLine($"\nAudit entries written by these {cases.Length} checks: {written}");
Console.WriteLine(written == cases.Length ? "PASS  every decision was recorded" : "FAIL  audit count mismatch");

// Prove the audit log records the RESULT faithfully (README warns about a bug where it doesn't).
var recentDenied = await db.AuditLog.Where(a => a.CustomerId == acme.Id && a.ResourceName == "billing" && a.PermissionName == "read")
    .OrderByDescending(a => a.Timestamp).FirstAsync();
Console.WriteLine(recentDenied.Result == AccessResult.Denied
    ? "PASS  denied 'read billing' was logged as Denied (not Allowed)"
    : $"FAIL  denied action logged as {recentDenied.Result}");

Console.WriteLine($"\n=== {pass} passed, {fail} failed ===");
Environment.Exit(fail == 0 ? 0 : 1);

